model discussion_board_moderator_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Associated moderator account. {@link discussion_board_moderator.id}.
  discussion_board_moderator_id String @db.Uuid

  /// IP address used during the session for security monitoring.
  ip String

  /// Connection URL that initiated the session.
  href String

  /// Referrer URL that led to the session initiation.
  referrer String

  /// Timestamp when the session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the session expired or will expire (null if active).
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  moderator discussion_board_moderator @relation(fields: [discussion_board_moderator_id], references: [id], onDelete: Cascade, map: "discussion_board_moderator_sessions_discussion_board_m_6d6ac0ef")

  // spellchecker: ignore-next-line
  @@index([discussion_board_moderator_id, created_at], map: "discussion_board_moderator_sessions_discussion_board_m_086f6f8b")
}

schemas.schema-03-content.prisma:
/// Articles created by users on economic or political topics.
///
/// This table stores the primary content pieces in the discussion board
/// system. Articles can be created by members or moderators and must go
/// through an approval process before becoming publicly visible. Each
/// article is associated with one or more categories and can include file
/// attachments.
///
/// Articles have a lifecycle managed through their status field, starting as
/// 'pending' and moving to 'approved' or 'rejected' based on moderator
/// review. The system maintains full audit trails of article changes through
/// snapshot tables and preserves deleted content for compliance purposes.
///
/// @namespace Content
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_articles {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The member or moderator who created this article. {@link
  /// discussion_board_member.id} or {@link discussion_board_moderator.id}.
  author_id String @db.Uuid

  /// The primary category this article belongs to. {@link
  /// discussion_board_categories.id}.
  category_id String @db.Uuid

  /// The title of the article. Must be between 5-200 characters.
  title String

  /// The main content body of the article. Must be between 10-10,000
  /// characters.
  content String

  /// The current approval status of the article. Valid values: 'pending',
  /// 'approved', 'rejected'.
  status String

  /// Timestamp when the article was first created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the article was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the article was deleted (soft delete).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  author discussion_board_member @relation(fields: [author_id], references: [id], onDelete: Cascade)
  category discussion_board_categories @relation(fields: [category_id], references: [id], onDelete: Cascade)

  discussion_board_comments discussion_board_comments[]
  discussion_board_attachments discussion_board_attachments[]
  discussion_board_article_categories discussion_board_article_categories[]

  @@index([author_id, created_at])
  @@index([category_id, created_at])
  @@index([status, created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([content(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Comments made by users on discussion board articles.
///
/// This table stores user comments on articles. Comments can be made by any
/// authenticated user (member or moderator) and are associated with a
/// specific article. Each comment includes text content and maintains
/// timestamps for creation and modification.
///
/// Comments support the core engagement functionality of the discussion
/// board, allowing users to respond to articles and participate in
/// discussions. Like articles, comments support soft deletion to preserve
/// discussion context while allowing inappropriate content to be removed.
///
/// @namespace Content
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The article this comment belongs to. {@link discussion_board_articles.id}.
  article_id String @db.Uuid

  /// The member or moderator who created this comment. {@link
  /// discussion_board_member.id} or {@link discussion_board_moderator.id}.
  author_id String @db.Uuid

  /// The comment text content. Must be between 1-2,000 characters.
  content String

  /// Timestamp when the comment was first created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the comment was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the comment was deleted (soft delete).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  article discussion_board_articles @relation(fields: [article_id], references: [id], onDelete: Cascade)
  author discussion_board_member @relation(fields: [author_id], references: [id], onDelete: Cascade)

  @@index([article_id, created_at])
  @@index([author_id, created_at])
  @@index([content(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-04-media.prisma:
/// File attachments associated with discussion board articles.
///
/// This table stores metadata for files attached to articles in the
/// discussion board. Each attachment is linked to a specific article and
/// contains information about the file including its name, storage path,
/// type, and upload time. Attachments support both image and document files
/// as specified in the requirements.
///
/// The system allows multiple attachments per article (up to 5 images and 3
/// documents according to functional requirements). Attachments are managed
/// through the article lifecycle and are not directly accessible without
/// article context.
///
/// When articles are deleted, their attachments are also removed as part of
/// the content management process. File storage paths reference the actual
/// files stored in the system's file storage infrastructure.
///
/// Attachments maintain traceability to the original uploader through a
/// polymorphic relationship to either a member or moderator who created the
/// article to which this attachment belongs.
///
/// @namespace Media
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_attachments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The article to which this attachment belongs. {@link
  /// discussion_board_articles.id}.
  discussion_board_article_id String @db.Uuid

  /// Original name of the uploaded file as provided by the user. This
  /// preserves the user's file naming convention while the system uses unique
  /// identifiers for actual file storage.
  file_name String

  /// Path to the file in the storage system. This is a unique identifier
  /// generated by the system for secure file access and management.
  file_path String

  /// MIME type of the file (e.g., image/jpeg, application/pdf). Used to
  /// determine how to handle and display the file appropriately.
  file_type String

  /// Size of the file in bytes. Used for storage management and to enforce
  /// file size limits as specified in the requirements.
  file_size Int @db.Integer

  /// Timestamp when the attachment was uploaded and created in the system.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the attachment metadata was last modified.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the attachment was soft deleted. Null if the attachment is
  /// active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  article discussion_board_articles @relation(fields: [discussion_board_article_id], references: [id], onDelete: Cascade)

  // spellchecker: ignore-next-line
  @@index([discussion_board_article_id, created_at], map: "discussion_board_attachments_discussion_board_article__663ecfce")
  @@index([file_type])
  @@index([created_at])
}

schemas.schema-05-categories.prisma:
/// Discussion board categories that organize articles by topic.
///
/// This table defines the available categories that can be assigned to
/// articles. The system
/// is designed with exactly two categories as specified in requirements:
/// economic and political.
/// Each category has a unique name and can be associated with multiple
/// articles through the
/// article_categories junction table.
///
/// Categories support soft deletion to maintain historical references while
/// allowing for
/// administrative management. The system can be extended with additional
/// categories in
/// the future without requiring schema changes.
///
/// @namespace Categories
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The name of the category (e.g., economic, political). Must be unique
  /// across all categories.
  name String

  /// A detailed description of what type of content belongs in this category.
  description String?

  /// Timestamp when the category was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the category was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the category was deleted (soft delete).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_articles discussion_board_articles[]
  discussion_board_article_categories discussion_board_article_categories[]

  @@unique([name])
  @@index([created_at])
  @@index([deleted_at])
  @@index([name, deleted_at])
}

/// Junction table linking articles to their assigned categories.
///
/// This table establishes the many-to-many relationship between articles and
/// categories,
/// allowing articles to be classified under one or more categories. Each
/// record represents
/// an association between a single article and a single category.
///
/// The table includes temporal fields to track when associations were
/// created, supporting
/// audit trails and historical analysis of content categorization. Soft
/// deletion is
/// implemented to preserve historical data while allowing for
/// re-categorization.
///
/// This entity has primary stance because users need to independently manage
/// these
/// associations, search across articles by category, and perform
/// administrative operations
/// on category assignments regardless of parent context.
///
/// @namespace Categories
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_article_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to the article. {@link discussion_board_articles.id}.
  discussion_board_article_id String @db.Uuid

  /// Reference to the category. {@link discussion_board_categories.id}.
  discussion_board_category_id String @db.Uuid

  /// Timestamp when the article-category association was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the article-category association was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the article-category association was deleted (soft delete).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  article discussion_board_articles @relation(fields: [discussion_board_article_id], references: [id], onDelete: Cascade, map: "discussion_board_article_categories_discussion_board_a_69ca7429")
  // spellchecker: ignore-next-line
  category discussion_board_categories @relation(fields: [discussion_board_category_id], references: [id], onDelete: Cascade, map: "discussion_board_article_categories_discussion_board_c_92a8c56a")

  // spellchecker: ignore-next-line
  @@unique([discussion_board_article_id, discussion_board_category_id], map: "discussion_board_article_categories_discussion_board_a_d24a46b3")
  // spellchecker: ignore-next-line
  @@index([discussion_board_article_id], map: "discussion_board_article_categories_discussion_board_a_cdfd5f09")
  // spellchecker: ignore-next-line
  @@index([discussion_board_category_id], map: "discussion_board_article_categories_discussion_board_c_82b730fc")
  @@index([created_at])
  @@index([deleted_at])
}

